import{_ as t,o as d,c as a,a3 as o}from"./chunks/framework.BLaSdaBb.js";const u=JSON.parse('{"title":"刻","description":"","frontmatter":{},"headers":[],"relativePath":"workflow/naceb/advanced/tick.md","filePath":"workflow/naceb/advanced/tick.md","lastUpdated":1788343005000}'),c={name:"workflow/naceb/advanced/tick.md"};function r(n,e,s,l,i,p){return d(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="刻" tabindex="-1">刻 <a class="header-anchor" href="#刻" aria-label="Permalink to &quot;刻&quot;">​</a></h1><p>刻（tick）是NACEB协调三个FSMController的统一推进机制，负责队列调度与层间状态同步。</p><p>各层在一刻中的具体动作见<a href="./../processing/task#调度">Task</a>、<a href="./../processing/pipeline#调度">Pipeline</a>与<a href="./../processing/event#调度">Event</a>。</p><h2 id="刻发生" tabindex="-1">刻发生 <a class="header-anchor" href="#刻发生" aria-label="Permalink to &quot;刻发生&quot;">​</a></h2><p>刻可以由以下来源激活：</p><table tabindex="0"><thead><tr><th>来源</th><th>时机</th></tr></thead><tbody><tr><td>基础时钟</td><td>每50ms调用一次</td></tr><tr><td><code>start()</code></td><td>Event离开<code>idle</code>后</td></tr><tr><td><code>resume()</code></td><td>Event离开<code>paused</code>后</td></tr><tr><td>Task收尾</td><td><code>execute()</code>进入<code>done</code>、<code>failure</code>或<code>stopped</code>后</td></tr><tr><td>Task停止或重启</td><td>Task进入<code>stopped</code>或重新进入<code>pending</code>后</td></tr><tr><td>快进刻</td><td>上一刻报告发生推进后</td></tr></tbody></table><p><code>alertTick()</code>执行期间会自锁。此时到达的其他激活请求会被丢弃，不会排队累积。</p><h3 id="基础时钟" tabindex="-1">基础时钟 <a class="header-anchor" href="#基础时钟" aria-label="Permalink to &quot;基础时钟&quot;">​</a></h3><p><code>ensureClock()</code>确保全局只存在一个50ms定时器。</p><p>定时器每次触发时先通过<code>EventFSMController.hasLive()</code>判断是否仍需运行：</p><table tabindex="0"><thead><tr><th>Event状态</th><th>保持时钟</th><th>原因</th></tr></thead><tbody><tr><td><code>idle</code>、<code>paused</code></td><td>否</td><td>等待外部<code>start()</code>或<code>resume()</code></td></tr><tr><td><code>blocked</code>、<code>queue</code>、<code>activating</code>、<code>processing</code>、<code>pending</code></td><td>是</td><td>仍需调度或同步</td></tr><tr><td><code>done</code>、<code>failure</code>，未启用<code>bypassConsume</code></td><td>是</td><td>等待外部消费</td></tr><tr><td><code>done</code>、<code>failure</code>，启用<code>bypassConsume</code></td><td>否</td><td>Event层会自动消费</td></tr></tbody></table><p>没有需要保持时钟的Event时，定时器会停止。之后创建Event、调用<code>start()</code>或<code>resume()</code>会再次执行<code>ensureClock()</code>。</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>未消费的普通终局Event会持续保持基础时钟运行。</p><p>若不需要取得结果，应使用自动消费机制。</p></div><h3 id="快进刻" tabindex="-1">快进刻 <a class="header-anchor" href="#快进刻" aria-label="Permalink to &quot;快进刻&quot;">​</a></h3><p>三个Controller中任意一个报告本刻发生推进时，NACEB会通过<code>setTimeout(..., 0)</code>立即激活下一刻。</p><p>因此50ms只是基础时钟的兜底间隔，不是状态转移的最小间隔。</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>队列持续可推进时，NACEB会通过快进刻连续运行。</p><p>Controller报告的<code>moved</code>表示本刻完成了一次推进尝试，不严格等同于状态值发生改变。</p><p>被<code>VetoT</code>否决的可重试转移也会触发快进刻，使下一刻重新计算条件。</p></div><h2 id="刻发生时" tabindex="-1">刻发生时 <a class="header-anchor" href="#刻发生时" aria-label="Permalink to &quot;刻发生时&quot;">​</a></h2><p><code>alertTick()</code>激活一刻，并按固定顺序等待三个Controller：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TaskFSMController.nextTick()</span></span>
<span class="line"><span>  → PipelineFSMController.nextTick()</span></span>
<span class="line"><span>    → EventFSMController.nextTick()</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>顺序从下层到上层，使下层已经产生的结果可以在同一刻继续向上传递。</p><h2 id="注意" tabindex="-1">注意 <a class="header-anchor" href="#注意" aria-label="Permalink to &quot;注意&quot;">​</a></h2><p>Hook会被<code>nextTick()</code>等待，因此耗时Hook会阻塞当前刻。</p><p>纯观测应使用<a href="./observability/event">EventBus</a>。</p>`,24)])])}const b=t(c,[["render",r]]);export{u as __pageData,b as default};
